import sys

def main():
    if len(sys.argv) < 2:
        return

    gff_file = sys.argv[1]
    feature_counts = {}
    total_cds_bp = 0

    with open(gff_file, 'r') as f:
        for line in f:
            line = line.strip()
            # Skip blank lines and comments
            if not line or line.startswith('#'):
                continue

            parts = line.split('\t')
            if len(parts) < 5:
                continue

            feature_type = parts[2]
            start = int(parts[3])
            end = int(parts[4])

            # Count feature type
            feature_counts[feature_type] = feature_counts.get(feature_type, 0) + 1

            # Sum CDS lengths
            if feature_type == 'CDS':
                total_cds_bp += (end - start + 1)

    # Print feature counts sorted alphabetically by type
    for feature_type in sorted(feature_counts.keys()):
        print(f"{feature_type}\t{feature_counts[feature_type]}")

    # Print total CDS bp
    print(f"total_cds_bp\t{total_cds_bp}")

if __name__ == "__main__":
