#!/usr/bin/env python3
import sys

def main():
    if len(sys.argv) != 2:
        return

    vcf_file = sys.argv[1]

    kept = 0
    snv = 0
    indel = 0
    transitions = 0
    transversions = 0

    with open(vcf_file, 'r') as f:
        for line in f:
            if line.startswith('#'):
                continue

            parts = line.strip().split('\t')
            if len(parts) < 8:
                continue

            ref = parts[3]
            qual = parts[5]
            filter_field = parts[6]
            info = parts[7]

            # Check FILTER is PASS
            if filter_field != 'PASS':
                continue

            # Check QUAL >= 30
            try:
                qual_val = float(qual)
                if qual_val < 30:
                    continue
            except ValueError:
                continue

            # Check DP >= 10 in INFO
            dp = None
            for item in info.split(';'):
                if '=' in item:
                    key, value = item.split('=', 1)
                    if key == 'DP':
                        try:
                            dp = int(value)
                            break
                        except ValueError:
                            continue

            if dp is None or dp < 10:
                continue

            # Record passes all filters
            kept += 1

            # Count SNVs and indels per ALT allele
            alt = parts[4]
            alt_alleles = alt.split(',')

            for alt_allele in alt_alleles:
                if alt_allele == '.':
                    continue

                if len(ref) == 1 and len(alt_allele) == 1:
                    snv += 1

                    ref_base = ref.upper()
                    alt_base = alt_allele.upper()

                    if ref_base == alt_base:
                        continue

                    # Transitions: A<->G, C<->T
                    if (ref_base == 'A' and alt_base == 'G') or \
                       (ref_base == 'G' and alt_base == 'A') or \
                       (ref_base == 'C' and alt_base == 'T') or \
                       (ref_base == 'T' and alt_base == 'C'):
                        transitions += 1
                    else:
                        transversions += 1
                else:
                    indel += 1

    # Calculate Ti/Tv ratio
    if transversions > 0:
        titv = transitions / transversions
    else:
        titv = 0.0

    print(f"kept={kept} snv={snv} indel={indel} titv={titv:.3f}")

if __name__ == "__main__":
    main()
